// In header (template.h)
template <typename T>
class Service {
    T data;
public:
    T compute();
};

// In implementation (template.cpp)
template <typename T>
T Service<T>::compute() {
    return data * 2;
}

// EXPLICIT INSTANTIATION DEFINITION
// Generates machine code for these types in this translation unit.
template class Service<int>;
template Service<float>::compute();

// Prevents linker errors if Service<int> is used elsewhere
// without its definition being visible.
// (Avoids redundant implicit instantiations.)
